import sys, json, random, collections
sys.path.insert(0, "/app/tmp/t")
from run import run_json
import ref

def rhex(rng, n=None):
    if n is None: n = rng.randint(0, 5)
    return "".join(rng.choice("0123456789abcdef") for _ in range(2 * n))

def mkf(rng, level):
    r = rng.random()
    if r < 0.1: return {"type": "PADDING"}
    if r < 0.15: return {"type": "PING"}
    if r < 0.3: return {"type": "CRYPTO", "offset": rng.randint(0, 10), "data_hex": rhex(rng)}
    if r < 0.6:
        return {"type": "STREAM", "id": rng.choice([0,2,4,6,8,10]), "offset": rng.randint(0, 10),
                "data_hex": rhex(rng), "fin": rng.random() < 0.3}
    if r < 0.72: return {"type": "RESET_STREAM", "id": rng.choice([0,2,4]), "final_size": rng.randint(0, 12)}
    if r < 0.8: return {"type": "STOP_SENDING", "id": rng.choice([0,4])}
    if r < 0.9: return {"type": "ACK", "ranges": [[0, rng.randint(0, 8)]]}
    if r < 0.96: return {"type": "CLOSE", "app": rng.random() < 0.5, "code": rng.randint(0, 30)}
    return {"type": "UNKNOWN"}

def mktrace(rng, tid):
    cfg = {"early": rng.random() < 0.5, "overlap": rng.choice(["reject", "first"]),
           "buffer_packets": rng.randint(0, 5), "idle_ms": rng.choice([0, 0, 4, 12]),
           "max_streams_bidi": rng.randint(0, 4), "max_streams_uni": rng.randint(0, 4),
           "max_stream_data": rng.randint(0, 16), "max_data": rng.randint(0, 40),
           "crypto_limit": rng.randint(0, 16),
           "sent": {"I": [[0, 8]], "H": [[0, 8]], "A": [[0, 8]]}}
    events = []
    t = 0
    pn = 0
    for _ in range(rng.randint(0, 10)):
        t += rng.choice([0, 1, 3, 6, 10])
        r = rng.random()
        if r < 0.15:
            events.append({"t": t, "op": "key", "level": rng.choice(["I","H","Z","A"]),
                           "action": rng.choice(["install","discard"])})
        elif r < 0.2:
            events.append({"t": t, "op": "tick"})
        else:
            k = rng.randint(1, 3)
            pkts = []
            for _ in range(k):
                lv = rng.choice(["A","A","Z","I","H"])
                pkts.append({"level": lv, "pn": pn, "auth": rng.random() < 0.9,
                             "frames": [mkf(rng, lv) for _ in range(rng.randint(0, 4))]})
                pn += 1
            pkts.sort(key=lambda p: p["level"] == "A")
            events.append({"t": t, "op": "datagram", "bytes": rng.choice([1200, 1200, 1199]),
                           "packets": pkts})
    return {"id": tid, "config": cfg, "events": events}

stats = collections.Counter()
seed0 = int(sys.argv[1]) if len(sys.argv) > 1 else 9000000
n = int(sys.argv[2]) if len(sys.argv) > 2 else 200
bad = 0
for i in range(n):
    rng = random.Random(seed0 + i)
    ntr = rng.randint(1, 8)
    doc = {"version": 1, "traces": [mktrace(rng, "t%d" % k) for k in range(ntr)]}
    rc, out, err = run_json(doc)
    if rc != 0:
        print("RC!=0", seed0 + i, err[:200]); bad += 1; continue
    got = json.loads(out); want = ref.run(doc)
    if got != want:
        bad += 1
        print("MISMATCH seed", seed0 + i)
        print("input:", json.dumps(doc)[:3000])
        for g, w in zip(got["results"], want["results"]):
            if g != w:
                print(" got:", json.dumps(g)[:900])
                print(" want:", json.dumps(w)[:900])
        if bad >= 2: break
    for tr in got["results"]:
        stats["state:" + tr["connection"]["state"]] += 1
        for p in tr["packets"]:
            stats["p:" + p["status"] + "/" + p["reason"]] += 1
print("mismatches:", bad, "of", n)
for k, v in sorted(stats.items()): print("  %-40s %d" % (k, v))
PYEOF
